import { describe, expect, it } from 'vitest';
import { componentDiagram } from '../../../../src/domain/diagrams/component-diagram.js';

// RF-601, RF-603, RF-508: the component diagram of the target architecture, generated by code.

describe('componentDiagram', () => {
  it('RF-601 draws one node per component and an arrow per dependency', () => {
    const diagram = componentDiagram([
      { name: 'Web', dependsOn: ['Service'] },
      { name: 'Service', dependsOn: ['Database', 'Unknown'] },
      { name: 'Database', dependsOn: [] },
    ]);

    expect(diagram.split('\n')).toEqual([
      'flowchart LR',
      '  c1["Web"]',
      '  c2["Service"]',
      '  c3["Database"]',
      '  c1 --> c2',
      '  c2 --> c3',
    ]);
  });

  it('RF-603 codes every character of a name that could end the label or add a link', () => {
    const diagram = componentDiagram([
      { name: 'A"] --> B; click A "javascript:x"', dependsOn: [] },
    ]);

    expect(diagram.split('\n')).toHaveLength(2);
    const [, node] = diagram.split('\n');
    expect(node?.startsWith('  c1["')).toBe(true);
    expect(node?.endsWith('"]')).toBe(true);
    expect(node?.slice(6, -2)).not.toMatch(/["[\]>]/u);
  });
});
